// Extract video ID from YouTube URL
const youtubeUrl = $input.item.json.youtube_url;
let videoId = '';

// Handle different YouTube URL formats
if (youtubeUrl.includes('youtu.be/')) {
  videoId = youtubeUrl.split('youtu.be/')[1].split('?')[0];
} else if (youtubeUrl.includes('youtube.com/watch?v=')) {
  videoId = youtubeUrl.split('v=')[1].split('&')[0];
} else if (youtubeUrl.includes('youtube.com/embed/')) {
  videoId = youtubeUrl.split('embed/')[1].split('?')[0];
}

return {
  json: {
    youtube_url: youtubeUrl,
    video_id: videoId,
    client_email: $input.item.json.client_email || '',
    client_name: $input.item.json.client_name || 'Client'
  }
};

// Parse the ChatGPT response and prepare data for social posts
const response = $input.item.json.message?.content || $input.item.json.text;
let hooks = [];

try {
  // Try to parse JSON from the response
  const jsonMatch = response.match(/\[.*\]/s) || response.match(/\{.*\}/s);
  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    hooks = Array.isArray(parsed) ? parsed : [parsed];
  }
} catch (e) {
  // If parsing fails, create a basic structure
  hooks = [{ hook_text: response, engagement_potential: 8 }];
}

return {
  json: {
    youtube_url: $('Extract Video ID').item.json.youtube_url,
    video_id: $('Extract Video ID').item.json.video_id,
    transcript: $('RapidAPI - Extract Transcript').item.json.transcript,
    hooks: hooks,
    client_email: $('Extract Video ID').item.json.client_email,
    client_name: $('Extract Video ID').item.json.client_name,
    top_hook: hooks[0]?.hook_text || '',
    all_hooks_text: hooks.map(h => h.hook_text).join('\n\n')
  }
};

