// Combine all social media posts and prepare for Google Drive storage
const baseData = $('Parse Hooks Data').item.json;
const xPosts = $('ChatGPT - Create X Posts').item.json;
const linkedinPosts = $('ChatGPT - Create LinkedIn Posts').item.json;
const instagramPosts = $('ChatGPT - Create Instagram Posts').item.json;
const vizardResponse = $('Vizard AI - Create Shorts').item.json;

// Parse social media posts
function extractPosts(response) {
  const content = response.message?.content || response.text || JSON.stringify(response);
  try {
    const jsonMatch = content.match(/\[.*\]/s);
    if (jsonMatch) {
      return JSON.parse(jsonMatch[0]);
    }
  } catch (e) {}
  return [{ content: content }];
}

const xPostsArray = extractPosts(xPosts);
const linkedinPostsArray = extractPosts(linkedinPosts);
const instagramPostsArray = extractPosts(instagramPosts);

// Create formatted content for documents
const xPostsText = xPostsArray.map((p, i) => `POST ${i + 1}:\n${p.content || p.post}\n`).join('\n---\n\n');
const linkedinPostsText = linkedinPostsArray.map((p, i) => `POST ${i + 1}:\n${p.content || p.post}\n`).join('\n---\n\n');
const instagramPostsText = instagramPostsArray.map((p, i) => `POST ${i + 1}:\n${p.caption || p.content}\n\nHashtags: ${p.hashtags || ''}\n`).join('\n---\n\n');

const hooksText = baseData.hooks.map((h, i) => 
  `HOOK ${i + 1} (Engagement: ${h.engagement_potential || 'N/A'}/10):\n${h.hook_text}\n${h.context ? 'Context: ' + h.context : ''}\n${h.timestamp ? 'Timestamp: ' + h.timestamp : ''}`
).join('\n\n---\n\n');

const timestamp = new Date().toISOString().replace(/[:.]/g, '-').slice(0, -5);
const folderName = `YouTube_Content_${baseData.video_id}_${timestamp}`;

return {
  json: {
    ...baseData,
    folder_name: folderName,
    timestamp: timestamp,
    x_posts_text: xPostsText,
    linkedin_posts_text: linkedinPostsText,
    instagram_posts_text: instagramPostsText,
    hooks_text: hooksText,
    vizard_video_id: vizardResponse.video_id || vizardResponse.id || 'processing',
    vizard_status: vizardResponse.status || 'submitted'
  }
};

